private const val API="https://api.lib.social/api"
private const val IMAGE="https://img2.imglib.info"
private const val UA="Mozilla/5.0 (Linux; Android 10) AppleWebKit/537.36 Chrome/120 Mobile Safari/537.36"
private val io=Executors.newSingleThreadExecutor()
data class Manga(val id:Int,val slug:String,val name:String,val cover:String?,val site:Int=2,val desc:String="")
data class Chapter(val id:Int,val vol:String,val num:String,val name:String="",val branches:List<Int> = emptyList())

object Net {
 fun get(path:String, query:String="", site:Int?=2):String { val u=URL(API+path+(if(query.isEmpty())"" else "?$query")); val c=u.openConnection() as HttpURLConnection; c.connectTimeout=18000;c.readTimeout=25000;c.setRequestProperty("User-Agent",UA);c.setRequestProperty("Referer","https://slashlib.me/"); if(site!=null)c.setRequestProperty("site",site.toString()); try { return c.inputStream.bufferedReader().use{it.readText()} } finally {c.disconnect()} }
 fun enc(s:String)=URLEncoder.encode(s,"UTF-8")
 fun manga(j:JSONObject):Manga { val cover=j.optJSONObject("cover"); val url=cover?.optString("thumbnail").takeUnless{it.isNullOrBlank()} ?: cover?.optString("default"); val name=j.optString("rus_name").takeIf{it.isNotBlank()}?:j.optString("name").ifBlank{j.optString("eng_name","Без названия")}; return Manga(j.optInt("id"),j.optString("slug_url").ifBlank{j.optInt("id").toString()},name,url,j.optInt("site",j.optInt("site_id",2))) }
 fun catalog(q:String,page:Int=1):List<Manga> { val query="site_id%5B%5D=2&site_id%5B%5D=1"+(if(q.isNotBlank())"&q=${enc(q)}" else "")+(if(page>1)"&page=$page" else ""); val d=JSONObject(get("/manga",query,null)).optJSONArray("data")?:JSONArray();return (0 until d.length()).mapNotNull{try{manga(d.getJSONObject(it))}catch(_:Exception){null}} }
 fun chapters(m:Manga):List<Chapter>{ val d=JSONObject(get("/manga/${enc(m.slug)}/chapters",site=m.site)).optJSONArray("data")?:JSONArray(); return (0 until d.length()).mapNotNull{try{val x=d.getJSONObject(it); val branches=x.optJSONArray("branches")?:JSONArray(); val ids=(0 until branches.length()).mapNotNull{branches.optJSONObject(it)?.optInt("branch_id")}; Chapter(x.optInt("id"),x.optString("volume"),x.optString("number"),x.optString("name"),ids)}catch(_:Exception){null}}.sortedWith(compareBy({it.vol.toDoubleOrNull()?:0.0},{it.num.toDoubleOrNull()?:0.0})) }
 fun pages(m:Manga,c:Chapter):List<String>{ val base="number=${enc(c.num)}&volume=${enc(c.vol)}"; val attempts=c.branches.map{base+"&branch_id=$it"}+base; var last=""; for(q in attempts){try{val d=JSONObject(get("/manga/${enc(m.slug)}/chapter",q,m.site)).optJSONObject("data")?.optJSONArray("pages")?:continue; val urls=(0 until d.length()).mapNotNull{d.optJSONObject(it)?.optString("url")?.takeIf{it.isNotBlank()}}; if(urls.isNotEmpty())return urls}catch(e:Exception){last=e.message?:"ошибка"}};throw IOException(last.ifBlank{"Пустая глава"}) }
}
class MainActivity:AppCompatActivity(){
 private val store by lazy{Local(this)}; private var query=""; private var page=1; private var busy=false; private lateinit var root:LinearLayout
 override fun onCreate(savedInstanceState:Bundle?){super.onCreate(savedInstanceState); window.statusBarColor=Color.rgb(245,242,250);window.navigationBarColor=Color.rgb(245,242,250);window.decorView.systemUiVisibility=View.SYSTEM_UI_FLAG_LIGHT_STATUS_BAR; home() }
 private fun base(title:String,subtitle:String?=null){ root=LinearLayout(this).apply{orientation=1;setBackgroundColor(Color.rgb(248,246,251))}; val top=LinearLayout(this).apply{orientation=1;setPadding(20,16,20,8)}; top.addView(TextView(this).apply{text=textTitle(title)});if(subtitle!=null)top.addView(TextView(this).apply{text=subtitle;textSize=13f;setTextColor(0xff686570)});root.addView(top);setContentView(root) }
 private fun textTitle(s:String):CharSequence=s
 private fun titleView(s:String,size:Float=23f)=TextView(this).apply{text=s;textSize=size;setTextColor(0xff24212b);setPadding(0,8,0,12)}
 private fun btn(s:String,action:()->Unit)=Button(this).apply{text=s;setOnClickListener{action()}}
 private fun scroll():ScrollView { val sc=ScrollView(this);root.addView(sc,LinearLayout.LayoutParams(-1,-1));return sc }
 private fun home(){base("Slashlib","Android · SlashLib / MangaLib");val sc=scroll();val box=LinearLayout(this).apply{orientation=1;setPadding(16,8,16,24)};sc.addView(box);box.addView(btn("🔎 Поиск",::search));box.addView(btn("⭐ Избранное",::favorites));box.addView(btn("🔖 Закладки",::bookmarks));box.addView(btn("🕘 Недавние",::history));box.addView(btn("☁️ Синхронизация",::syncDialog));box.addView(titleView("Популярное",18f));loadPopular(box) }
 private fun loadPopular(box:LinearLayout){busy=true;box.addView(TextView(this).apply{text="Загружаю каталог…"});io.execute{try{val list=Net.catalog("");runOnUiThread{busy=false;box.removeViewAt(box.childCount-1);list.take(20).forEach{m->box.addView(mangaRow(m){details(m)})}}}catch(e:Exception){runOnUiThread{busy=false;box.addView(TextView(this).apply{text="Ошибка сети: ${e.message}"})}}}}
 private fun search(){base("Поиск");val sc=scroll();val box=LinearLayout(this).apply{orientation=1;padding(12)};sc.addView(box);val field=EditText(this).apply{hint="Название манги / манхвы"};box.addView(field);box.addView(btn("Найти") {query=field.text.toString();page=1;searchResults(box,query)});field.setOnEditorActionListener{_,_,_->query=field.text.toString();page=1;searchResults(box,query);true}; }
 private fun searchResults(box:LinearLayout,q:String){box.removeViews(2,box.childCount-2);box.addView(TextView(this).apply{text="Ищу…"});io.execute{try{val results=Net.catalog(q);runOnUiThread{box.removeViewAt(box.childCount-1);results.forEach{m->box.addView(mangaRow(m){details(m)})}}}catch(e:Exception){runOnUiThread{box.addView(TextView(this).apply{text=e.message?:"Ошибка"})}}}}
 private fun mangaRow(m:Manga,click:()->Unit):View {val row=LinearLayout(this).apply{orientation=0;setPadding(12,10,12,10);gravity=Gravity.CENTER_VERTICAL;setBackgroundColor(Color.WHITE);setOnClickListener{click()}};val img=ImageView(this).apply{layoutParams=LinearLayout.LayoutParams(96,132);scaleType=ImageView.ScaleType.CENTER_CROP};if(m.cover!=null)Glide.with(this).load(m.cover).into(img);row.addView(img);val text=LinearLayout(this).apply{orientation=1;padding(12)};text.addView(TextView(this).apply{text=m.name;textSize=16f;setTextColor(0xff22212a)});text.addView(TextView(this).apply{text="Открыть тайтл";textSize=12f;setTextColor(0xff66636e)});row.addView(text);return row }
 private fun details(m:Manga){base(m.name);val sc=scroll();val box=LinearLayout(this).apply{orientation=1;padding(16)};sc.addView(box);m.cover?.let{val im=ImageView(this).apply{layoutParams=LinearLayout.LayoutParams(180,250);scaleType=ImageView.ScaleType.CENTER_CROP};Glide.with(this).load(it).into(im);box.addView(im)};box.addView(btn(if(store.isFav(m))"★ В избранном" else "☆ Добавить в избранное"){store.toggleFav(m);details(m)});box.addView(btn("Скачать главы (пока по одной)"){Toast.makeText(this,"Открывайте главу и сохраняйте страницы для офлайн чтения",Toast.LENGTH_LONG).show()});box.addView(titleView("Главы",18f));box.addView(TextView(this).apply{text="Загрузка глав…"});io.execute{try{val ch=Net.chapters(m);runOnUiThread{box.removeViewAt(box.childCount-1);ch.reversed().forEach{c->box.addView(btn("Том ${c.vol} · Глава ${c.num}${if(c.name.isNotBlank())" — ${c.name}" else ""}"){reader(m,c)})}}}catch(e:Exception){runOnUiThread{box.addView(TextView(this).apply{text=e.message?:"Не удалось загрузить главы"})}}}}
 private fun reader(m:Manga,c:Chapter){base("Глава ${c.num}",m.name);val sc=scroll();val list=LinearLayout(this).apply{orientation=1};sc.addView(list);list.addView(TextView(this).apply{text="Загрузка страниц…";padding(20)});io.execute{try{val pages=Net.pages(m,c);store.saveRecent(m,c);runOnUiThread{list.removeAllViews();pages.forEachIndexed{idx,url->val im=ImageView(this).apply{adjustViewBounds=true;scaleType=ImageView.ScaleType.FIT_CENTER;layoutParams=LinearLayout.LayoutParams(-1,-2);setBackgroundColor(Color.BLACK)};Glide.with(this).load(url).into(im);list.addView(im)};list.addView(btn("🔖 Закладка главы"){store.bookmark(m,c);Toast.makeText(this,"Закладка сохранена",Toast.LENGTH_SHORT).show()})}}catch(e:Exception){runOnUiThread{list.removeAllViews();list.addView(TextView(this).apply{text="Ошибка загрузки: ${e.message}";padding(16)});list.addView(btn("Повторить"){reader(m,c)})}}}}
 private fun favorites(){base("Избранное");val sc=scroll();val b=LinearLayout(this).apply{orientation=1;padding(10)};sc.addView(b);store.favs().forEach{b.addView(mangaRow(it){details(it)})};if(b.childCount==0)b.addView(TextView(this).apply{text="Пока пусто"})}
 private fun bookmarks(){base("Закладки");val sc=scroll();val b=LinearLayout(this).apply{orientation=1;padding(10)};sc.addView(b);store.bookmarks().forEach{(m,c)->b.addView(btn("${m.name} · глава ${c.num}"){reader(m,c)})};if(b.childCount==0)b.addView(TextView(this).apply{text="Закладок нет"})}
 private fun history(){base("Недавние");val sc=scroll();val b=LinearLayout(this).apply{orientation=1;padding(10)};sc.addView(b);store.recent().forEach{(m,c)->b.addView(btn("${m.name} · глава ${c.num}"){reader(m,c)})};if(b.childCount==0)b.addView(TextView(this).apply{text="История чтения пуста"})}
 private fun syncDialog(){val input=EditText(this).apply{hint="GitHub token (gist)"};input.setText(store.token());AlertDialog.Builder(this).setTitle("Синхронизация Gist").setMessage("Создайте GitHub personal access token с разрешением gist. Синхронизируются избранное, закладки и недавнее чтение.").setView(input).setPositiveButton("Сохранить и синхронизировать"){_,_->store.setToken(input.text.toString());io.execute{try{GistSync.sync(store);runOnUiThread{Toast.makeText(this,"Синхронизация выполнена",Toast.LENGTH_LONG).show()}}catch(e:Exception){runOnUiThread{Toast.makeText(this,"Sync: ${e.message}",Toast.LENGTH_LONG).show()}}}}.setNeutralButton("Синхронизировать сейчас"){_,_->io.execute{try{GistSync.sync(store);runOnUiThread{Toast.makeText(this,"Синхронизировано",Toast.LENGTH_LONG).show()}}catch(e:Exception){runOnUiThread{Toast.makeText(this,e.message,Toast.LENGTH_LONG).show()}}}}.setNegativeButton("Закрыть",null).show()}
 private fun LinearLayout.padding(v:Int){setPadding(v,v,v,v)}
}
class Local(c:Context){private val p=c.getSharedPreferences("slashlib",0);private fun read(k:String)=JSONArray(p.getString(k,"[]"));private fun write(k:String,a:JSONArray){p.edit().putString(k,a.toString()).apply()}
 private fun json(m:Manga)=JSONObject().put("id",m.id).put("slug",m.slug).put("name",m.name).put("cover",m.cover).put("site",m.site)
 private fun parse(o:JSONObject)=Manga(o.optInt("id"),o.optString("slug"),o.optString("name"),o.optString("cover").takeIf{it.isNotBlank()&&it!="null"},o.optInt("site",2))
 fun isFav(m:Manga)=favs().any{it.slug==m.slug};fun toggleFav(m:Manga){val a=JSONArray();favs().filter{it.slug!=m.slug}.forEach{a.put(json(it))};if(!isFav(m))a.put(json(m));write("fav",a)};fun favs()=(0 until read("fav").length()).mapNotNull{try{parse(read("fav").getJSONObject(it))}catch(_:Exception){null}}
 fun bookmark(m:Manga,c:Chapter){val a=read("book");a.put(JSONObject().put("m",json(m)).put("id",c.id).put("v",c.vol).put("n",c.num).put("name",c.name));write("book",a)};fun bookmarks()=records("book");fun saveRecent(m:Manga,c:Chapter){val a=JSONArray();records("recent").filter{it.first.slug!=m.slug}.forEach{a.put(JSONObject().put("m",json(it.first)).put("id",it.second.id).put("v",it.second.vol).put("n",it.second.num))};a.put(JSONObject().put("m",json(m)).put("id",c.id).put("v",c.vol).put("n",c.num));write("recent",a)};fun recent()=records("recent")
 private fun records(k:String):List<Pair<Manga,Chapter>>{val a=read(k);return (0 until a.length()).mapNotNull{try{val o=a.getJSONObject(it);val m=parse(o.getJSONObject("m"));m to Chapter(o.optInt("id"),o.optString("v"),o.optString("n"),o.optString("name"))}catch(_:Exception){null}}}
 fun gistId()=p.getString("gist","" )?:"";fun setGistId(id:String){p.edit().putString("gist",id).apply()}
 fun mergeJson(remote:JSONObject):JSONObject {val fav=JSONArray();val allFav=(favs()+remoteList(remote,"favorites")).distinctBy{it.slug};allFav.forEach{fav.put(json(it))};val books=JSONArray();(bookmarks()+remoteRecords(remote,"bookmarks")).distinctBy{it.first.slug+"#"+it.second.id}.forEach{(m,c)->books.put(JSONObject().put("m",json(m)).put("id",c.id).put("v",c.vol).put("n",c.num).put("name",c.name))};val recentArr=JSONArray();(recent()+remoteRecords(remote,"recent")).distinctBy{it.first.slug}.take(100).forEach{(m,c)->recentArr.put(JSONObject().put("m",json(m)).put("id",c.id).put("v",c.vol).put("n",c.num).put("name",c.name))};return JSONObject().put("version",1).put("updated",System.currentTimeMillis()).put("favorites",fav).put("bookmarks",books).put("recent",recentArr)}
 private fun remoteList(o:JSONObject,k:String):List<Manga> = try{val a=o.optJSONArray(k)?:JSONArray();(0 until a.length()).mapNotNull{try{parse(a.getJSONObject(it))}catch(_:Exception){null}}}catch(_:Exception){emptyList()}
 private fun remoteRecords(o:JSONObject,k:String):List<Pair<Manga,Chapter>> = try{val a=o.optJSONArray(k)?:JSONArray();(0 until a.length()).mapNotNull{try{val x=a.getJSONObject(it);val m=parse(x.getJSONObject("m"));m to Chapter(x.optInt("id"),x.optString("v"),x.optString("n"),x.optString("name"))}catch(_:Exception){null}}}catch(_:Exception){emptyList()}
 fun importJson(o:JSONObject){val fav=o.optJSONArray("favorites")?:JSONArray();write("fav",fav);write("book",o.optJSONArray("bookmarks")?:JSONArray());write("recent",o.optJSONArray("recent")?:JSONArray())}
 fun token()=p.getString("token","");fun setToken(t:String){p.edit().putString("token",t.trim()).apply()}
}

object GistSync {
 private const val FILE="slashlib-android-sync.json"
 private fun request(token:String,method:String,url:String,body:String?=null):String{val c=(URL(url).openConnection() as HttpURLConnection);c.requestMethod=method;c.connectTimeout=20000;c.readTimeout=20000;c.setRequestProperty("Authorization","Bearer $token");c.setRequestProperty("Accept","application/vnd.github+json");c.setRequestProperty("X-GitHub-Api-Version","2022-11-28");c.setRequestProperty("User-Agent","Slashlib-Android");if(body!=null){c.doOutput=true;c.setRequestProperty("Content-Type","application/json");c.outputStream.use{it.write(body.toByteArray())}};val code=c.responseCode;val stream=if(code in 200..299)c.inputStream else c.errorStream;val text=stream?.bufferedReader()?.use{it.readText()}?:"";c.disconnect();if(code !in 200..299)throw IOException("GitHub HTTP $code: $text");return text}
 fun sync(local:Local){val token=local.token().trim();if(token.isBlank())throw IOException("Сначала сохраните токен GitHub");val remote=JSONArray(request(token,"GET","https://api.github.com/gists"));var gistId=local.gistId();var gist:JSONObject?=null;if(gistId.isNotBlank()){try{gist=JSONObject(request(token,"GET","https://api.github.com/gists/$gistId"))}catch(_:Exception){gist=null}};if(gist==null){for(i in 0 until remote.length()){val g=remote.optJSONObject(i)?:continue;val files=g.optJSONObject("files")?:continue;if(files.has(FILE)){gist=g;gistId=g.optString("id");break}}};val remoteDoc=try{val f=gist?.optJSONObject("files")?.optJSONObject(FILE);val content=f?.optString("content").orEmpty();if(content.isNotBlank())JSONObject(content)else JSONObject()}catch(_:Exception){JSONObject()};val merged=local.mergeJson(remoteDoc);val files=JSONObject().put(FILE,JSONObject().put("content",merged.toString()));val payload=JSONObject().put("description","Slashlib Android cross-device sync").put("public",false).put("files",files);val response=if(gistId.isNotBlank())request(token,"PATCH","https://api.github.com/gists/$gistId",payload.toString())else request(token,"POST","https://api.github.com/gists",payload.toString());local.setGistId(JSONObject(response).optString("id",gistId));local.importJson(merged)}
}
